package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.service.content.CatalogAnalysisContentBaselineService;
import java.util.*;
import java.util.function.Supplier;
import javax.sql.DataSource;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.*;
import org.springframework.transaction.support.*;
import tools.jackson.databind.json.JsonMapper;

/** Actual content metadata/body/key provider only; original generation authority is a separate consumer. */
class CatalogAnalysisContentBaselineTest {
    GenerationJdbcStoreTest f;CatalogAnalysisContentBaselineService provider;DataSourceTransactionManager manager;boolean mysql(){return false;}
    @BeforeEach void fixture(){f=mysql()?new GenerationJdbcStoreMySqlTest():new GenerationJdbcStoreTest();f.fixture();f.jdbc.execute("DROP TABLE IF EXISTS contents");String json=mysql()?"JSON":"CLOB";f.jdbc.execute("CREATE TABLE contents(kind VARCHAR(32),id VARCHAR(64) PRIMARY KEY,entity_id VARCHAR(64),revision BIGINT,body_revision BIGINT,input_job_id VARCHAR(64),body_hash_v1 BINARY(32),body_json "+json+",content_key_json "+json+",state VARCHAR(32))"+(mysql()?" ENGINE=InnoDB":""));manager=new DataSourceTransactionManager(f.source);provider=new CatalogAnalysisContentBaselineService(f.source,manager,"agent");}
    <T>T tx(boolean read,Supplier<T> work){var transaction=new TransactionTemplate(manager);transaction.setReadOnly(read);transaction.setIsolationLevel(read?TransactionDefinition.ISOLATION_REPEATABLE_READ:TransactionDefinition.ISOLATION_READ_COMMITTED);return transaction.execute(s->work.get());}
    String body(String category,String entity){return JdbcFrozenInputs.canonical(JsonMapper.shared().createObjectNode().put("category",category).put("entity_id",entity).put("title","Fictional analysis").set("sections",JsonMapper.shared().createArrayNode()));}
    tools.jackson.databind.JsonNode key(String category,String id,String hash,String root){return JsonMapper.shared().createObjectNode().put("kind","content_version").put("content_kind",category).put("content_id",id).put("revision",1).put("body_hash",hash).put("input_job_id",root);}
    void insert(String category,String entity,String id){String body=body(category,entity),hash=CanonicalJson.hash(CanonicalJson.Domain.CONTENT,CanonicalJson.parse(body));var version=key(category,id,hash,"fictional-old-root");f.jdbc.update("INSERT INTO contents VALUES(?,?,?,?,?,?,?,?,?,?)",category,id,entity,2,1,"fictional-old-root",HexFormat.of().parseHex(hash),body,JdbcFrozenInputs.canonical(version),"draft");}
    @Test void FourCategoriesCompleteCurrentNativeBaselineAndDistinctStableNewId(){var ids=new HashSet<String>();for(String category:List.of("agent","skill","workflow","model")){String entity="fictional-"+category;String id=CatalogAnalysisContentBaselineService.newContentId(category,entity);assertTrue(ids.add(id));var service=new CatalogAnalysisContentBaselineService(f.source,manager,category);assertNull(service.find(entity,id));insert(category,entity,id);var observed=service.find(entity,id);assertEquals(category,observed.category());assertEquals(entity,observed.entityId());assertEquals(2,observed.revision());assertEquals(1,observed.bodyRevision());assertEquals("fictional-old-root",observed.inputRoot());assertEquals(CanonicalJson.hash(CanonicalJson.Domain.CONTENT,CanonicalJson.parse(observed.bodyJson())),observed.bodyHash());assertEquals(observed,tx(false,()->service.lockInWriter(entity,id)));assertEquals(observed,tx(true,()->service.findInSnapshot(entity,id)));assertFalse(observed.toString().contains("fictional"));}assertEquals(0,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class));}
    @Test void ActualCatalogOriginalSuccessfulContentProvidesItsNativeReplacementBaseline(){var outer=new CatalogDayAnalysisEligibilityTest(){@Override boolean mysql(){return CatalogAnalysisContentBaselineTest.this.mysql();}};var actual=outer.new Fixture();actual.terminal("model");actual.completeSource();var service=new CatalogAnalysisContentBaselineService(actual.f.source,actual.f.tx,"model");var observed=service.find("fictional-entity","fictional-analysis");assertNotNull(observed);assertEquals(1,observed.revision());assertEquals(1,observed.bodyRevision());assertEquals(CatalogPreviousAnalysisTest.Fixture.ROOT,observed.inputRoot());assertEquals(observed,actual.write(()->service.lockInWriter("fictional-entity","fictional-analysis")));assertEquals(2,actual.f.sends);}
    @Test void IdentityAliasesLegacyProofBodyHashKeyAndBlockedStateReject(){String id="fictional-target",entity="fictional-entity";insert("agent",entity,id);assertThrows(RuntimeException.class,()->provider.find(entity,"fictional-other-id"));assertThrows(RuntimeException.class,()->provider.find("fictional-other-entity",id));assertThrows(RuntimeException.class,()->new CatalogAnalysisContentBaselineService(f.source,manager,"model").find(entity,id));f.jdbc.update("UPDATE contents SET body_revision=NULL");assertThrows(RuntimeException.class,()->provider.find(entity,id));f.jdbc.update("UPDATE contents SET body_revision=1,body_hash_v1=?",new byte[32]);assertThrows(RuntimeException.class,()->provider.find(entity,id));f.jdbc.update("UPDATE contents SET body_hash_v1=?",HexFormat.of().parseHex(CanonicalJson.hash(CanonicalJson.Domain.CONTENT,CanonicalJson.parse(body("agent",entity)))));f.jdbc.update("UPDATE contents SET content_key_json=NULL");assertThrows(RuntimeException.class,()->provider.find(entity,id));f.jdbc.update("UPDATE contents SET content_key_json=?",JdbcFrozenInputs.canonical(key("agent",id,CanonicalJson.hash(CanonicalJson.Domain.CONTENT,CanonicalJson.parse(body("agent",entity))),"fictional-wrong-root")));assertThrows(RuntimeException.class,()->provider.find(entity,id));f.jdbc.update("UPDATE contents SET content_key_json=?,state='blocked'",JdbcFrozenInputs.canonical(key("agent",id,CanonicalJson.hash(CanonicalJson.Domain.CONTENT,CanonicalJson.parse(body("agent",entity))),"fictional-old-root")));assertThrows(RuntimeException.class,()->provider.find(entity,id));}
    @Test void SnapshotObservesOneVersionAndWriterLocksFreshThenWholeCallerRollsBack(){String id="fictional-target",entity="fictional-entity";insert("agent",entity,id);var observed=provider.find(entity,id);f.jdbc.update("UPDATE contents SET revision=3");assertEquals(3,tx(false,()->provider.lockInWriter(entity,id)).revision());assertEquals(2,observed.revision());assertThrows(RuntimeException.class,()->tx(false,()->{f.jdbc.update("UPDATE contents SET revision=4");assertEquals(4,provider.lockInWriter(entity,id).revision());throw new IllegalStateException("fictional rollback");}));assertEquals(3,provider.find(entity,id).revision());}
    @Test void MultipleOwnedTargetsAndFullBodyCapacityRejectWithoutTruncation(){insert("agent","fictional-entity","fictional-target");insert("agent","fictional-entity","fictional-second");assertThrows(RuntimeException.class,()->provider.find("fictional-entity","fictional-target"));f.jdbc.update("DELETE FROM contents WHERE id='fictional-second'");String huge=JdbcFrozenInputs.canonical(JsonMapper.shared().createObjectNode().put("category","agent").put("entity_id","fictional-entity").put("title","x".repeat(262144)));f.jdbc.update("UPDATE contents SET body_json=?",huge);assertThrows(RuntimeException.class,()->provider.find("fictional-entity","fictional-target"));}
    @Test void StrictTransactionRolesAndMandatoryClosedCategoryZeroIo(){assertThrows(RuntimeException.class,()->provider.findInSnapshot("fictional-entity","fictional-target"));assertThrows(RuntimeException.class,()->provider.lockInWriter("fictional-entity","fictional-target"));assertThrows(RuntimeException.class,()->tx(true,()->provider.find("fictional-entity","fictional-target")));assertThrows(RuntimeException.class,()->tx(true,()->provider.lockInWriter("fictional-entity","fictional-target")));assertThrows(RuntimeException.class,()->tx(false,()->provider.findInSnapshot("fictional-entity","fictional-target")));var source=mock(DataSource.class);var tx=mock(PlatformTransactionManager.class);for(String category:List.of("agent","skill","workflow","model"))assertNotNull(new CatalogAnalysisContentBaselineService(source,tx,category));verifyNoInteractions(source,tx);assertThrows(RuntimeException.class,()->new CatalogAnalysisContentBaselineService(source,tx,"news_tech"));}
    @Test void NativeContentRowRemainsLockedUntilWriterFinishes(){insert("agent","fictional-entity","fictional-target");if(!mysql())return;tx(false,()->{assertNotNull(provider.lockInWriter("fictional-entity","fictional-target"));try(var connection=f.source.getConnection();var statement=connection.createStatement()){statement.execute("SET SESSION innodb_lock_wait_timeout=1");var rejected=assertThrows(java.sql.SQLException.class,()->statement.executeUpdate("UPDATE contents SET revision=3 WHERE id='fictional-target'"));assertEquals(1205,rejected.getErrorCode());}catch(java.sql.SQLException failure){throw new IllegalStateException(failure);}return true;});assertEquals(2,provider.find("fictional-entity","fictional-target").revision());}
}
